const body = $input.first().json.body || $input.first().json;

if (!body || !body.context) {
  throw new Error('Invalid request payload: missing clinical context snapshot.');
}

const context = body.context;
const deterministicFindings = body.deterministicFindings || [];
const proposedPrescription = body.proposedPrescription || null;

const systemInstruction = `
Eres el Asistente Clínico de SAMED (Sistema de Apoyo Médico para Evaluación y Decisión).
Tu rol es EXCLUSIVAMENTE CONSULTIVO Y DE SÍNTESIS CLÍNICA para un prototipo con datos sintéticos.

INVARIANTES CRÍTICOS:
1. Los hallazgos determinísticos (deterministicFindings) proporcionados son hallazgos determinísticos autoritativos dentro del prototipo SAMED. NUNCA los contradigas, descartes, reemplaces ni declares que están equivocados.
2. La síntesis que generas apoya la decisión; el profesional médico retiene la AUTORIDAD DECISORIA FINAL.
3. NO puedes crear, autorizar ni aprobar recetas médicas bajo ninguna circunstancia.
4. Trata los datos clínicos no disponibles con precisión semántica: DATO FALTANTE ≠ NORMAL (MISSING !== NORMAL, UNKNOWN !== NORMAL, STALE !== NORMAL, UNAVAILABLE !== NORMAL).
5. Si existen brechas de datos o análisis pendientes (por ejemplo, creatinina o función renal no registrada), resáltalos explícitamente en dataAvailabilityGaps.
6. Genera tu salida ÚNICAMENTE en formato JSON válido conforme al esquema requerido, sin bloques markdown ni texto adicional.
`;

const userPrompt = `
Por favor sintetiza el contexto clínico del paciente y los hallazgos determinísticos observados.

DATOS DEL PACIENTE:
ID: ${context.patient?.id || 'Desconocido'}
Condiciones activas: ${JSON.stringify(context.conditions || [])}
Alergias registradas: ${JSON.stringify(context.allergies || [])}
Medicamentos actuales: ${JSON.stringify(context.medications || [])}
Observaciones y datos de laboratorio: ${JSON.stringify(context.observations || [])}
Brechas de datos conocidas: ${JSON.stringify(context.dataPoints || {})}

HALLAZGOS DETERMINÍSTICOS (Evidencia obligatoria):
${JSON.stringify(deterministicFindings, null, 2)}

PROPUESTA DE PRESCRIPCIÓN MÉDICA (Si existe):
${JSON.stringify(proposedPrescription, null, 2)}

Genera una síntesis clínica estructurada en JSON con:
- id: identificador único con prefijo 'ca-summary-'
- patientId: '${context.patient?.id || 'pat-unknown'}'
- summary: síntesis narrativa de la situación clínica y las implicaciones de los hallazgos determinísticos
- clinicalConsiderations: arreglo de cadenas con observaciones clínicas relevantes
- dataAvailabilityGaps: arreglo de objetos { key: string, status: string, reason?: string }
- deterministicFindingsReferenced: arreglo con los IDs de los hallazgos determinísticos referenciados
- generatedAt: marca temporal ISO 8601 actual
- role: 'clinical_assistant'
`;

return [{
  json: {
    patientId: context.patient?.id || 'pat-unknown',
    systemInstruction,
    userPrompt,
    deterministicFindings,
    originalPayload: body
  }
}];

const item = $input.first().json;

if (item.error) {
  return [{
    json: {
      error: true,
      code: 'GEMINI_API_ERROR',
      message: `Gemini API Error: ${typeof item.error === 'object' ? JSON.stringify(item.error) : String(item.error)}`
    }
  }];
}

let parsed = null;

try {
  const candidateText = item.candidates?.[0]?.content?.parts?.[0]?.text;
  if (candidateText) {
    parsed = typeof candidateText === 'string' ? JSON.parse(candidateText) : candidateText;
  } else if (item.summary && item.id) {
    parsed = item;
  } else {
    throw new Error('Gemini API response did not contain valid candidate text or summary.');
  }
} catch (err) {
  return [{
    json: {
      error: true,
      code: 'MALFORMED_PROVIDER_OUTPUT',
      message: `Failed to parse Gemini provider response: ${err.message}`
    }
  }];
}

const validStatuses = ['AVAILABLE', 'MISSING', 'STALE', 'UNAVAILABLE', 'UNKNOWN'];

if (
  !parsed ||
  typeof parsed !== 'object' ||
  typeof parsed.id !== 'string' ||
  !parsed.id.trim() ||
  typeof parsed.patientId !== 'string' ||
  !parsed.patientId.trim() ||
  typeof parsed.summary !== 'string' ||
  !parsed.summary.trim() ||
  !Array.isArray(parsed.clinicalConsiderations) ||
  !Array.isArray(parsed.dataAvailabilityGaps) ||
  !Array.isArray(parsed.deterministicFindingsReferenced) ||
  typeof parsed.generatedAt !== 'string' ||
  !parsed.generatedAt.trim() ||
  parsed.role !== 'clinical_assistant'
) {
  return [{
    json: {
      error: true,
      code: 'INVALID_CLINICAL_ASSESSMENT_STRUCTURE',
      message: 'Gemini provider output is missing required contract fields or has invalid types.'
    }
  }];
}

for (const gap of parsed.dataAvailabilityGaps) {
  if (
    !gap ||
    typeof gap !== 'object' ||
    typeof gap.key !== 'string' ||
    !gap.key.trim() ||
    !validStatuses.includes(gap.status)
  ) {
    return [{
      json: {
        error: true,
        code: 'INVALID_CLINICAL_ASSESSMENT_STRUCTURE',
        message: 'Gemini provider output contains invalid dataAvailabilityGaps structure.'
      }
    }];
  }
}

if (!parsed.clinicalConsiderations.every(item => typeof item === 'string')) {
  return [{
    json: {
      error: true,
      code: 'INVALID_CLINICAL_ASSESSMENT_STRUCTURE',
      message: 'Gemini provider output contains non-string items in clinicalConsiderations.'
    }
  }];
}

if (!parsed.deterministicFindingsReferenced.every(item => typeof item === 'string')) {
  return [{
    json: {
      error: true,
      code: 'INVALID_CLINICAL_ASSESSMENT_STRUCTURE',
      message: 'Gemini provider output contains non-string items in deterministicFindingsReferenced.'
    }
  }];
}

const normalized = {
  id: String(parsed.id),
  patientId: String(parsed.patientId),
  summary: String(parsed.summary),
  clinicalConsiderations: parsed.clinicalConsiderations.map(String),
  dataAvailabilityGaps: parsed.dataAvailabilityGaps.map(g => {
    const gapObj = {
      key: String(g.key),
      status: g.status
    };
    if (g.reason !== undefined && g.reason !== null) {
      gapObj.reason = String(g.reason);
    }
    return gapObj;
  }),
  deterministicFindingsReferenced: parsed.deterministicFindingsReferenced.map(String),
  generatedAt: String(parsed.generatedAt),
  role: 'clinical_assistant'
};

return [{ json: normalized }];
